// RequestEditorFn is the function signature for the RequestEditor callback function
type RequestEditorFn func(ctx context.Context, req *http.Request) error

// Doer performs HTTP requests.
//
// The standard http.Client implements this interface.
type HttpRequestDoer interface {
	Do(req *http.Request) (*http.Response, error)
}

// RetryConfig configures retry behavior for idempotent operations.
type RetryConfig struct {
	// MaxRetries is the TOTAL number of attempts for an idempotent operation,
	// including the initial request — not the number of retries after the first
	// attempt (default: 3, so up to 3 attempts total). A value of 0 is accepted
	// as a compatibility exception and means a single attempt with no retry; a
	// negative value is a configuration error rejected by WithRetryConfig and
	// doWithRetry.
	MaxRetries int
	// BaseDelay is the initial delay between retries (default: 1s)
	BaseDelay time.Duration
	// MaxDelay is the maximum delay between retries (default: 30s)
	MaxDelay time.Duration
	// Multiplier is the exponential backoff multiplier (default: 2.0)
	Multiplier float64
}

// DefaultRetryConfig returns the default retry configuration.
func DefaultRetryConfig() RetryConfig {
	return RetryConfig{
		MaxRetries: 3,
		BaseDelay:  1 * time.Second,
		MaxDelay:   30 * time.Second,
		Multiplier: 2.0,
	}
}

// Client which conforms to the OpenAPI3 specification for this service.
type Client struct {
	// The endpoint of the server conforming to this interface, with scheme,
	// https://api.deepmap.com for example. This can contain a path relative
	// to the server, such as https://api.deepmap.com/dev-test, and all the
	// paths in the swagger spec will be appended to the server.
	Server string

	// Doer for performing requests, typically a *http.Client with any
	// customized settings, such as certificate chains.
	Client HttpRequestDoer

	// A list of callbacks for modifying requests which are generated before sending over
	// the network.
	RequestEditors []RequestEditorFn

	// RetryConfig for idempotent operations
	RetryConfig RetryConfig

	// Logger for debug output (optional)
	Logger *slog.Logger
}

// ClientOption allows setting custom parameters during construction
type ClientOption func(*Client) error

// Creates a new Client, with reasonable defaults
func NewClient(server string, opts ...ClientOption) (*Client, error) {
	// create a client with sane default values
	client := Client{
		Server:      server,
		RetryConfig: DefaultRetryConfig(),
	}
	// mutate client and add all optional params
	for _, o := range opts {
		if err := o(&client); err != nil {
			return nil, err
		}
	}
	// ensure the server URL always has a trailing slash
	if !strings.HasSuffix(client.Server, "/") {
		client.Server += "/"
	}
	// create httpClient, if not already present
	if client.Client == nil {
		client.Client = &http.Client{}
	}
	return &client, nil
}

// WithHTTPClient allows overriding the default Doer, which is
// automatically created using http.Client. This is useful for tests.
func WithHTTPClient(doer HttpRequestDoer) ClientOption {
	return func(c *Client) error {
		c.Client = doer
		return nil
	}
}

// WithRequestEditorFn allows setting up a callback function, which will be
// called right before sending the request. This can be used to mutate the request.
func WithRequestEditorFn(fn RequestEditorFn) ClientOption {
	return func(c *Client) error {
		c.RequestEditors = append(c.RequestEditors, fn)
		return nil
	}
}

// effectiveMaxAttempts resolves RetryConfig.MaxRetries (a TOTAL attempt count)
// into the number of attempts an idempotent operation should make:
//   - MaxRetries < 0  → configuration error (a plain error; the low-level
//     generated package has no BasecampError usage type).
//   - MaxRetries == 0 → 1 attempt (compatibility exception; no retry).
//   - MaxRetries > 0  → MaxRetries attempts.
//
// Every non-error result is >= 1, so doWithRetry always makes at least one
// attempt (never returns a nil response with a nil error).
func (cfg RetryConfig) effectiveMaxAttempts() (int, error) {
	if cfg.MaxRetries < 0 {
		return 0, fmt.Errorf("basecamp: invalid RetryConfig: MaxRetries must be >= 0, got %d", cfg.MaxRetries)
	}
	if cfg.MaxRetries == 0 {
		return 1, nil
	}
	return cfg.MaxRetries, nil
}

// WithRetryConfig allows setting custom retry configuration for idempotent operations.
// It returns a configuration error if cfg.MaxRetries is negative.
func WithRetryConfig(cfg RetryConfig) ClientOption {
	return func(c *Client) error {
		if _, err := cfg.effectiveMaxAttempts(); err != nil {
			return err
		}
		c.RetryConfig = cfg
		return nil
	}
}

// WithLogger allows setting a custom logger for debug output.
func WithLogger(logger *slog.Logger) ClientOption {
	return func(c *Client) error {
		c.Logger = logger
		return nil
	}
}

// defaultRetryOn is behavior-model.json's declared default, applied only when an
// operation carries no x-basecamp-retry.retryOn — which cannot happen for a
// generated call site.
var defaultRetryOn = []int{http.StatusTooManyRequests, http.StatusServiceUnavailable}

// isRetryableStatus reports whether the status is in the operation's DECLARED
// retry_on set. The set is per-operation and exhaustive: a status the spec never
// declared retryable — including 500, 502, and 504 — is not retried, and is
// surfaced to the caller on the first attempt. ParseHTTPError still classifies
// those statuses as retryable errors for the caller's benefit; that is a
// caller-facing hint and deliberately does not widen this gate.
func isRetryableStatus(statusCode int, operationId string) bool {
	// Only an ABSENT entry falls back. A present-but-empty set is an operation
	// declaring "never retry on any status", which is not the same as declaring
	// nothing — collapsing the two would silently re-enable 429/503 retries on an
	// operation that opted out.
	retryOn, ok := operationRetryOn[operationId]
	if !ok {
		retryOn = defaultRetryOn
	}
	for _, status := range retryOn {
		if status == statusCode {
			return true
		}
	}
	return false
}

// captureReplayBody inspects the finalized first-attempt request and returns a
// closure that reproduces its body on later attempts, plus the ContentLength to
// restore each attempt. When retriable is false the body cannot be safely
// replayed, so the caller makes a single attempt streaming the body as-is.
//
// Replay contract (documented; net/http-consistent): req.GetBody, when present,
// DEFINES the request body for replay — exactly as the standard library's own
// redirect handling uses it. There is no reliable way to detect whether an
// editor mutated req.Body out of sync with req.GetBody (an editor can Reset the
// underlying reader in place, which no identity check can see), so we make
// GetBody authoritative: this attempt is ALSO normalized to send GetBody()'s
// bytes, so every attempt — first and retries — ships identical bytes. A
// retrying request's body is therefore changed by an editor only through
// req.GetBody (set req.Body and req.GetBody together, as net/http requires).
//
// A body WITHOUT a GetBody snapshot is an arbitrary, single-use stream. It is
// NOT buffered or retried: buffering would risk unbounded memory, and a blocking
// reader cannot be interrupted (there is no general way to abort an io.Reader),
// so such a request is sent exactly once. In-memory bodies that net/http can
// snapshot (*bytes.Reader/*bytes.Buffer/*strings.Reader — the readers the typed
// and generated builders use) already carry a GetBody and so replay normally;
// only a caller passing a genuinely streaming reader to a raw *WithBody method
// forgoes retries, which is the safe behavior for an unrewindable stream.
// sameReader reports whether two request bodies are the same value. Comparing
// io.ReadCloser interface values panics if their dynamic type is not comparable
// (e.g. a struct with a slice field used directly as the body); such a body was
// necessarily supplied by an editor, so recovering to false — "not the same",
// which disables replay — is the safe answer.
func sameReader(a, b io.ReadCloser) (same bool) {
	defer func() { _ = recover() }()
	return a == b
}

// captureReplayBody decides, once, how a retry reproduces the FIRST finalized
// request body. It never rewrites req.Body: attempt 1 always sends the body
// exactly as buildRequest + the request editors left it, so an editor that
// compresses/encrypts/transforms the payload (and sets matching headers) is
// honored — even when no retry occurs. builderBody is req.Body as buildRequest
// produced it, BEFORE the editors ran.
//
// A retry replays via req.GetBody, exactly as net/http replays a body on a
// 307/308 redirect. That is only sound when the builder's body survived the
// editors unchanged (so its GetBody still describes req.Body). If an editor
// REPLACED req.Body, the builder's GetBody is stale and the finalized bytes
// cannot be reproduced, so the request is sent once rather than retried with the
// wrong body. (An editor that mutates the body IN PLACE without updating GetBody
// is undetectable and, like a net/http redirect, would replay GetBody's
// snapshot; editors should replace the body, or keep req.GetBody in sync.)
func captureReplayBody(req *http.Request, builderBody io.ReadCloser, retryEligible bool) (replay func() (io.ReadCloser, error), contentLength int64, retriable bool, err error) {
	// A nil body (GET/HEAD): a retry reproduces the nil body faithfully.
	if req.Body == nil {
		return nil, req.ContentLength, true, nil
	}
	// An explicitly empty body (http.NoBody): always reproducible — replay the
	// stateless sentinel so retries send a non-nil empty body with identical
	// (empty) transfer framing.
	if req.Body == http.NoBody {
		return func() (io.ReadCloser, error) { return http.NoBody, nil }, req.ContentLength, true, nil
	}
	if !retryEligible {
		return nil, req.ContentLength, false, nil
	}
	// Replayable only if the builder's body survived the editors unchanged and
	// carries a usable GetBody. Probe GetBody (without disturbing the finalized
	// req.Body sent on attempt 1); on failure or an editor replacement, send once.
	if req.GetBody != nil && sameReader(req.Body, builderBody) {
		rc, gErr := req.GetBody()
		if gErr != nil {
			return nil, req.ContentLength, false, nil
		}
		_ = rc.Close()
		return req.GetBody, req.ContentLength, true, nil
	}
	return nil, req.ContentLength, false, nil
}

// closeOnceBody wraps a request body so Close is idempotent. doWithRetry installs
// a replay body before the request editors run (so a body-aware editor observes
// it), then owns that handle: it closes it after the editor phase regardless of
// whether an editor replaced req.Body — closing it here plus the routine close of
// the current req.Body would otherwise double-close the same handle when the
// editor left it in place, or leak it when the editor swapped it out.
type closeOnceBody struct {
	rc     io.ReadCloser
	closed bool
}

func (b *closeOnceBody) Read(p []byte) (int, error) { return b.rc.Read(p) }
func (b *closeOnceBody) Close() error {
	if b.closed {
		return nil
	}
	b.closed = true
	return b.rc.Close()
}

// doWithRetry executes a request with retry logic for idempotent operations.
func (c *Client) doWithRetry(ctx context.Context, buildRequest func() (*http.Request, error), isIdempotent bool, operationId string, reqEditors ...RequestEditorFn) (*http.Response, error) {
	// MaxRetries is a TOTAL attempt count. Re-validate here (not just in
	// WithRetryConfig) because RetryConfig is publicly mutable after client
	// construction.
	maxAttempts, err := c.RetryConfig.effectiveMaxAttempts()
	if err != nil {
		return nil, err
	}
	if !isIdempotent {
		maxAttempts = 1
	}
	// Apply the per-operation retry ceiling from x-basecamp-retry as an upper
	// bound on attempts: effective attempts = min(client cap, op ceiling). The
	// ceiling can only reduce attempts below the client cap, never raise them, so
	// a client that lowered its cap (e.g. to disable retries) is still honored.
	if opMax, ok := operationRetryMax[operationId]; ok && opMax > 0 && opMax < maxAttempts {
		maxAttempts = opMax
	}

	var lastResp *http.Response
	var lastErr error
	delay := c.RetryConfig.BaseDelay

	// Replay state captured from the first finalized request (see
	// captureReplayBody). buildRequest recreates the request from the caller's
	// now-drained io.Reader on every attempt, so the raw *WithBody methods would
	// otherwise ship an empty (or mid-stream) body on retries.
	var bodyReplay func() (io.ReadCloser, error)
	var replayContentLength int64
	retryEligible := isIdempotent && maxAttempts > 1

	// installReplay closes the current req.Body and swaps in a fresh replay of the
	// captured first-attempt body (or nil when there is no body), restoring
	// GetBody and ContentLength. It returns the installed handle (wrapped so Close
	// is idempotent) so a retry's pre-editor caller can own and close it after the
	// editor phase. On a retry it runs BOTH before applyEditors — so body-aware
	// editors (e.g. one computing a Digest/HMAC header) observe and sign the bytes
	// that will actually be sent — AND after, so the first finalized body stays
	// authoritative (an editor cannot change a retry's body).
	installReplay := func(req *http.Request) (io.ReadCloser, error) {
		if req.Body != nil {
			_ = req.Body.Close()
		}
		if bodyReplay == nil {
			req.Body = nil
			req.GetBody = nil
			req.ContentLength = replayContentLength
			return nil, nil
		}
		rc, bErr := bodyReplay()
		if bErr != nil {
			return nil, bErr
		}
		// Preserve the http.NoBody sentinel unwrapped: net/http keys request
		// framing off body identity — a wrapped NoBody has ContentLength 0 but is
		// not the sentinel, so Request.outgoingLength() reports -1 (unknown) and
		// the retry would switch to Transfer-Encoding: chunked, differing from the
		// first attempt's empty framing. http.NoBody's Close is already a no-op,
		// so it needs no close-once wrapper.
		var installed io.ReadCloser = rc
		if rc != http.NoBody {
			installed = &closeOnceBody{rc: rc}
		}
		req.Body = installed
		req.GetBody = bodyReplay
		req.ContentLength = replayContentLength
		return installed, nil
	}

	for attempt := 1; attempt <= maxAttempts; attempt++ {
		req, err := buildRequest()
		if err != nil {
			return nil, err
		}
		req = req.WithContext(ctx)

		// Capture the builder's body BEFORE the editors run so captureReplayBody
		// can tell (on attempt 1) whether an editor replaced it — a replaced body
		// is not safely reproducible for retries.
		var builderBody io.ReadCloser
		if attempt == 1 {
			builderBody = req.Body
		}

		// On a retry, install the replay body BEFORE editors so body-aware editors
		// sign the bytes that will actually be sent. We OWN this handle and close
		// it after the editor phase — even if an editor replaces req.Body (which
		// would otherwise orphan it). closeOnceBody makes the routine close below
		// a no-op when the editor left it in place.
		var preEditorBody io.ReadCloser
		if attempt > 1 {
			preEditorBody, err = installReplay(req)
			if err != nil {
				return nil, err
			}
		}

		editErr := c.applyEditors(ctx, req, reqEditors)
		if preEditorBody != nil {
			_ = preEditorBody.Close()
		}
		if editErr != nil {
			// Release whatever body the editors left (a replacement, or the
			// already-closed pre-editor handle — closeOnceBody makes this safe).
			if req.Body != nil {
				_ = req.Body.Close()
			}
			return nil, editErr
		}

		if attempt == 1 {
			// Snapshot the finalized first request's body exactly once; every
			// later attempt replays THIS body.
			replay, cl, retriable, capErr := captureReplayBody(req, builderBody, retryEligible)
			if capErr != nil {
				return nil, capErr
			}
			bodyReplay = replay
			replayContentLength = cl
			if !retriable {
				// The body is not safely replayable (an unrewindable stream with
				// no GetBody): send it once and do not retry.
				maxAttempts = 1
			}
		} else {
			// Re-install AFTER editors: the first finalized body wins, and any
			// editor body change (now closed) is discarded and refreshed.
			if _, err := installReplay(req); err != nil {
				return nil, err
			}
		}

		resp, err := c.Client.Do(req)
		if err != nil {
			lastErr = err
			if c.Logger != nil {
				c.Logger.Debug("request failed",
					"operation", operationId,
					"attempt", attempt,
					"error", err,
				)
			}
			// Network errors are retryable for idempotent operations
			if isIdempotent && attempt < maxAttempts {
				select {
				case <-ctx.Done():
					return nil, ctx.Err()
				case <-time.After(delay + time.Duration(rand.Int63n(int64(100*time.Millisecond)))):
				}
				delay = time.Duration(float64(delay) * c.RetryConfig.Multiplier)
				if delay > c.RetryConfig.MaxDelay {
					delay = c.RetryConfig.MaxDelay
				}
				continue
			}
			return nil, err
		}

		// Success or non-retryable status
		if !isRetryableStatus(resp.StatusCode, operationId) {
			return resp, nil
		}

		lastResp = resp
		if c.Logger != nil {
			c.Logger.Debug("retryable status received",
				"operation", operationId,
				"attempt", attempt,
				"status", resp.StatusCode,
			)
		}

		// Don't retry if not idempotent or last attempt
		if !isIdempotent || attempt >= maxAttempts {
			return resp, nil
		}

		// Close body before retry
		_ = resp.Body.Close()

		// For 429 responses, respect Retry-After header if present
		retryDelay := delay
		if resp.StatusCode == http.StatusTooManyRequests {
			if retryAfter := resp.Header.Get("Retry-After"); retryAfter != "" {
				if seconds, err := strconv.Atoi(retryAfter); err == nil && seconds > 0 {
					retryDelay = time.Duration(seconds) * time.Second
				}
			}
		}

		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(retryDelay + time.Duration(rand.Int63n(int64(100*time.Millisecond)))):
		}
		delay = time.Duration(float64(delay) * c.RetryConfig.Multiplier)
		if delay > c.RetryConfig.MaxDelay {
			delay = c.RetryConfig.MaxDelay
		}
	}

	if lastErr != nil {
		return nil, lastErr
	}
	return lastResp, nil
}

